INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Maschinensprache immer direkt von Menschen geschrieben wird. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Meist von Compilern erzeugt"}, {"text": "Ja", "correct": false, "because": "Zu komplex"}]'),
