('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat die Maschinensprache?', 5, '[{"text": "Binärcode", "correct": true, "because": "0 und 1"}, {"text": "Prozessorspezifisch", "correct": true, "because": "Abhängig von CPU"}, {"text": "Lesbar für Menschen", "correct": false, "because": "Nicht direkt lesbar"}, {"text": "Farblich markiert", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Maschinensprache ist die niedrigste Programmierebene. b) Sie ist immer plattformunabhängig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Plattformabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Maschinensprache in einem IT-System untersuche?', 4, '[{"text": "Befehlsstruktur", "correct": false, "because": "Kern der Sprache"}, {"text": "Prozessorarchitektur", "correct": false, "because": "Bestimmt Syntax"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Maschinensprache direkt von Programmierern genutzt wird?', 2, '[{"text": "Nein", "correct": true, "because": "Höhere Sprachen üblich"}, {"text": "Ja", "correct": false, "because": "Zu komplex"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich Maschinensprache analysiere?', 3, '[{"text": "Hardwareverständnis", "correct": true, "because": "Zeigt Funktionsweise"}, {"text": "Schnellste Programmierung", "correct": false, "because": "Analyse zählt"}, {"text": "Weniger Code", "correct": false, "because": "Nicht Ziel"}]'),
